"""Packages LocalPDF Hub into one executable with PyInstaller.

    npm ci && npm run build
    python -m pip install -r requirements-build.txt
    python build.py

The result is dist/LocalPDF-Hub (dist/LocalPDF-Hub.exe on Windows).
"""

import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent

# Generated by `npm run build` and kept out of git; without them the UI
# loads with no PDF previews, icons or font.
GENERATED_ASSETS = [
    "libs/pdf.min.mjs",
    "libs/pdf.worker.min.mjs",
    "libs/icons.svg",
    "libs/fonts/ibm-plex-sans-latin-400-normal.woff2",
]

# Modules loaded by name at runtime, which PyInstaller cannot see.
HIDDEN_IMPORTS = [
    "uvicorn.lifespan.on",
    "uvicorn.lifespan.off",
    "uvicorn.loops.auto",
    "uvicorn.loops.asyncio",
    "uvicorn.protocols.http.auto",
    "uvicorn.protocols.http.h11_impl",
    "uvicorn.protocols.websockets.auto",
    "pystray._win32",
]


def main() -> None:
    missing = [name for name in GENERATED_ASSETS if not (ROOT / "frontend" / name).is_file()]
    if missing:
        sys.exit(f"frontend/{missing[0]} is missing. Run: npm ci && npm run build")

    command = [
        sys.executable,
        "-m",
        "PyInstaller",
        "--noconfirm",
        "--clean",
        "--onefile",
        "--noconsole",
        "--name=LocalPDF-Hub",
        "--icon=frontend/icon.ico",
        "--paths=src",
        f"--add-data=frontend{os.pathsep}frontend",
        *(f"--hidden-import={name}" for name in HIDDEN_IMPORTS),
        "src/localpdf_hub/__main__.py",
    ]
    subprocess.run(command, cwd=ROOT, check=True)  # noqa: S603 -- fixed arguments


if __name__ == "__main__":
    main()
